import { cn } from "@/components/workspace-ui/lib/utils";

/**
 * The badges a component's files are marked with.
 *
 * These are the TypeScript and React marks rather than a generic page glyph,
 * so a row is identifiable before its name is read. They are drawn in
 * `currentColor` instead of their brand blues: the tree is one white column,
 * and two saturated logos in it would read as the only thing on the page
 * asking for attention.
 */

type IconProps = { className?: string };

