/** The badge for a file, chosen from its extension. */
export function FileTypeIcon({
  filename,
  className,
}: {
  filename: string;
  className?: string;
}) {
  if (filename.endsWith(".tsx")) return <ReactIcon className={className} />;
  if (filename.endsWith(".ts")) return <TypeScriptIcon className={className} />;

  return <FileIcon className={cn("shrink-0", className)} />;
}
